  assert.ok(ctx.state.chain.includes(t.id), "precondition: it was dotted");

  ctx.undo();
  const task = ctx.state.tasks.find((x) => x.id === t.id);
  assert.equal(task.title, "Old title", "one undo reverses the edit...");
