 quota=used()+80;
 await ctx.cloudPull();await syncSettle(30);
 assert.ok(ctx.state.tasks.some(task=>task.id==='remote'),'the newer cloud board is adopted after local capacity recovers: '+
  (shim.document.getElementById('toast')?.textContent||''));
