  const saved=new Map();const storage={getItem:k=>saved.get(k)||null,setItem:(k,v)=>saved.set(k,v),key:i=>[...saved.keys()][i],get length(){return saved.size;},removeItem:k=>saved.delete(k)};
  const a=moodRuntime(),b=moodRuntime();
